async function boot(){
const [elementary,middle]=await Promise.all(['elementary','middle'].map(async band=>{const response=await fetch('content/'+band+'.json');if(!response.ok)throw Error('Content unavailable');const data=await response.json();OpenPathContent.validate(data);return data}));
const middleSubjects=middle.subjects,middleProjects=middle.projects;window.elementarySubjects=elementary.subjects;window.elementaryProjects=elementary.projects;
let band='elementary';try{band=localStorage.getItem('openpath-band')==='middle'?'middle':'elementary'}catch{};let subjects=band==='middle'?middleSubjects:window.elementarySubjects;let projects=band==='middle'?middleProjects:window.elementaryProjects;const storageKey=()=>band==='middle'?'openpath-v1':'openpath-elementary-v1';const empty=()=>({version:1,mastered:[],attempts:[],reflections:{},minutes:0});let state=empty();let storageOK=true;try{let saved=JSON.parse(localStorage.getItem(storageKey()));if(OpenPathContent.validProgress(saved))state=saved;}catch{storageOK=false}let session=null;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const mastered=(s,i)=>state.mastered.includes(s.id+':'+i);const count=s=>s.lessons.filter((_,i)=>mastered(s,i)).length;const total=()=>subjects.reduce((n,s)=>n+count(s),0);function save(){try{localStorage.setItem(storageKey(),JSON.stringify(state))}catch{storageOK=false;toast('Storage is unavailable. Progress lasts only for this visit.')}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function card(s){let c=count(s);return `<article class="card"><div class="card-top"><span class="subject-icon ${s.id}">${esc(s.symbol)}</span><span class="tag">${c===3?'Completed':'3 short lessons'}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.topic)}</p><div class="progress-label"><span>Path progress</span><span>${c} / 3 skills</span></div><div class="track"><div style="width:${c/3*100}%"></div></div><div class="card-bottom"><span>◷ About 5 min / lesson</span><button data-start="${s.id}">${c===3?'Review':'Continue'} <span aria-hidden="true">＋</span></button></div></article>`}
function stats(){return `<div class="stats"><div class="stat"><span class="stat-icon">◷</span><div><strong>${state.minutes}</strong><small>Minutes practiced · all time</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>${total()} <span class="muted">/ 9</span></strong><small>Skills checked</small></div></div><div class="stat"><span class="stat-icon">◇</span><div><strong>${Object.keys(state.reflections).length}</strong><small>Project reflections</small></div></div></div>`}
function render(){const route=location.hash.slice(1)||'today';$('#band').value=band;document.querySelectorAll('nav a,.bottom>a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));const names={today:'My day',subjects:'Learning paths',projects:'Life skills lab',progress:'My progress',guide:'Guide workspace'};$('#crumb').textContent=names[route]||'My day';let html='';if(route==='today'||!names[route]){const next=subjects.find(s=>count(s)<3)||subjects[0];html=`<div class="intro"><div><div class="eyebrow">YOUR PACE. YOUR POSSIBILITIES.</div><h1>A little focus. A big step forward.</h1><p>Build your skills, follow your curiosity, and make today count.</p></div><span class="pill">✦ A fresh start</span></div><section class="focus"><div><div class="eyebrow">YOUR NEXT FOCUS SESSION</div><h2>${total()===9?'Keep your curiosity going.':esc(next.topic)}</h2><p>Start with one small lesson. Practice what you learn, then take it into the real world.</p><button class="btn white" data-start="${next.id}">${total()===9?'Review a lesson':'Start learning'}</button></div><div class="ring"><strong>${total()}<span style="font-size:20px"> / 9</span></strong><span>skills checked</span></div></section>${stats()}<div class="section-heading"><h2>Your learning paths</h2><a class="text-link" href="#subjects">Explore all paths</a></div><div class="grid">${subjects.map(card).join('')}</div><div class="lower"><section><div class="section-heading"><h2>More than academics</h2><span class="tag">LIFE SKILLS LAB</span></div><div class="lab"><span class="lab-number">01</span><div><div class="eyebrow">${esc(projects[0].skill)} · ${esc(projects[0].time)}</div><h3 style="margin-top:9px">${esc(projects[0].title)}</h3><p>${esc(projects[0].description)}</p><a class="text-link" href="#projects">Explore the project</a></div></div></section><section><div class="section-heading"><h2>A moment to reflect</h2></div><div class="note"><strong>Progress begins with a question.</strong><p>What’s one thing you understand today that felt tricky yesterday?</p><a class="text-link" style="display:block;margin-top:14px" href="#progress">See your progress</a></div></section></div>`}
if(route==='subjects')html=`<div class="intro"><div class="eyebrow">CORE ACADEMICS</div></div><h1>Build understanding, step by step.</h1><p class="muted">Read, practice, and check your understanding. Each path has three original sample lessons.</p><div class="grid">${subjects.map(card).join('')}</div><div class="notice">This demo uses one question per skill. A full mastery assessment needs more varied questions, spaced review, and educator judgment.</div>`;
if(route==='projects')html=`<div class="eyebrow">LEARN IT. LIVE IT.</div><h1>Life skills lab</h1><p class="muted">Go beyond the screen. Create something, work with others, and reflect on what you learned.</p>${projects.map(p=>`<article class="card project"><div class="eyebrow">${esc(p.skill)} · ${esc(p.time)}</div><h2 style="margin-top:14px">${esc(p.title)}</h2><p>${esc(p.description)}</p><ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><label for="${p.id}">What did you try, and what would you improve?</label><textarea id="${p.id}" maxlength="3000" placeholder="Write your reflection here…">${esc(state.reflections[p.id]||'')}</textarea><div class="actions"><button class="btn" data-save="${p.id}">Save reflection</button></div></article>`).join('')}`;
if(route==='progress')html=`<div class="eyebrow">SMALL STEPS ADD UP</div><h1>Your learning, in perspective.</h1>${stats()}<div class="grid">${subjects.map(card).join('')}</div><div class="section-heading"><h2>Recent practice</h2><button class="btn secondary" id="export">Export progress</button></div>${history()}<div class="notice">Progress is stored in this browser only. Export it before clearing browser data. Avoid including personal information in reflections.</div>`;
if(route==='guide')html=`<div class="eyebrow">GUIDE WORKSPACE · SINGLE-LEARNER DEMO</div><h1>Support the next small breakthrough.</h1><p class="muted">A view of practice on this device. Start a conversation where a learner needs support.</p>${stats()}<div class="table-wrap card"><table><thead><tr><th>Learning path</th><th>Skills checked</th><th>Suggested support</th></tr></thead><tbody>${subjects.map(s=>{const mistakes=state.attempts.filter(a=>a.subject===s.id&&!a.correct).length;return `<tr><td>${esc(s.name)}</td><td>${count(s)} of 3</td><td>${mistakes?'Revisit examples together':count(s)===3?'Try a real-world application':'Invite the learner to explain their thinking'}</td></tr>`}).join('')}</tbody></table></div><div class="section-heading"><h2>Practice evidence</h2></div>${history()}<div class="notice">This view shares the same local demo data; it is not a separate account or a protected teacher portal.</div>`;
$('#main').innerHTML=html+(!storageOK?'<p class="notice">Browser storage is unavailable; this visit’s progress may not persist.</p>':'');document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const v=document.getElementById(b.dataset.save).value.trim();if(!v)return toast('Write a reflection before saving.');state.reflections[b.dataset.save]=v;save();toast('Reflection saved on this device.');});if($('#export'))$('#export').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='openpath-'+band+'-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};}
function history(){if(!state.attempts.length)return '<div class="empty">Your story starts with one lesson. Begin a learning path to see your practice here.</div>';return `<div class="table-wrap card"><table><thead><tr><th>Lesson</th><th>Result</th><th>When</th></tr></thead><tbody>${state.attempts.slice(-10).reverse().map(a=>`<tr><td>${esc(a.title)}</td><td>${a.correct?'✓ Correct':'Practice again'}</td><td>${new Date(a.at).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div>`}
function start(id){let s=subjects.find(s=>s.id===id);if(!s)throw Error('Unknown learning path');let i=s.lessons.findIndex((_,i)=>!mastered(s,i));session={s,i:i<0?0:i,step:'read',choice:null,checked:false,started:Date.now()};drawLesson();if(!$('#lesson').open)$('#lesson').showModal();return {subject:id,lesson:session.i,title:s.lessons[session.i].title}}
function closeLesson(){if(session){state.minutes+=Math.floor((Date.now()-session.started)/60000);save();session=null}$('#lesson').close();render()}
function drawLesson(){let {s,i,step}=session,l=s.lessons[i];$('#lesson-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">${esc(s.name)} · LESSON ${i+1} / 3</span><button class="close" id="close" aria-label="Close lesson">×</button></div><h2>${esc(l.title)}</h2><p class="muted">${step==='read'?'Take a moment to understand the idea.':'Check your understanding.'}</p>${step==='read'?`<div class="lesson-copy">${esc(l.text)}</div><div class="actions"><button class="btn" id="practice">Try a question</button></div>`:`<h3>${esc(l.q)}</h3><div class="options" role="group" aria-label="Answer choices">${l.options.map((o,j)=>`<button class="option ${session.choice===j?'selected':''}" data-choice="${j}" aria-pressed="${session.choice===j}" ${session.checked?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}</div><div id="feedback" aria-live="polite">${session.checked?`<div class="feedback ${session.choice===l.answer?'':'retry'}"><strong>${session.choice===l.answer?'That’s right.':'Let’s work through it.'}</strong><br>${esc(session.choice===l.answer?l.why:l.hint)}</div>`:''}</div><div class="actions"><button class="btn secondary" id="hint">Show a hint</button>${session.checked?`<button class="btn" id="next">${session.choice!==l.answer?'Try again':i<2?'Next lesson':'Finish path'}</button>`:`<button class="btn" id="check" ${session.choice===null?'disabled':''}>Check answer</button>`}</div>`}`;$('#close').onclick=closeLesson;if($('#practice'))$('#practice').onclick=()=>{session.step='practice';drawLesson()};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{session.choice=Number(b.dataset.choice);drawLesson()});if($('#hint'))$('#hint').onclick=()=>{$('#feedback').innerHTML=`<div class="feedback">${esc(l.hint)}</div>`};if($('#check'))$('#check').onclick=()=>{if(session.checked||session.choice===null)return;session.checked=true;const correct=session.choice===l.answer;state.attempts.push({subject:s.id,title:l.title,correct,at:new Date().toISOString()});if(correct&&!mastered(s,i))state.mastered.push(s.id+':'+i);save();drawLesson()};if($('#next'))$('#next').onclick=()=>{if(session.choice!==l.answer){session.choice=null;session.checked=false;drawLesson()}else if(i<2){session.i++;session.step='read';session.choice=null;session.checked=false;drawLesson()}else{closeLesson();toast('Path complete. Take a break, then try a life skills project.')}}}
$('#band').onchange=()=>{if(session)closeLesson();save();band=$('#band').value;subjects=band==='middle'?middleSubjects:window.elementarySubjects;projects=band==='middle'?middleProjects:window.elementaryProjects;state=empty();try{localStorage.setItem('openpath-band',band);const saved=JSON.parse(localStorage.getItem(storageKey()));if(OpenPathContent.validProgress(saved))state=saved}catch{storageOK=false}render();toast('Switched to '+(band==='middle'?'middle':'elementary')+' school.')};$('#lesson').addEventListener('cancel',e=>{e.preventDefault();closeLesson()});window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_learning_path',description:'Open the next sample lesson in a learning path. Does not complete a lesson.',inputSchema:{type:'object',properties:{subject:{type:'string',enum:['math','reading','science']}},required:['subject'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length!==1||!subjects.some(s=>s.id===input.subject))throw Error('Choose math, reading, or science');return start(input.subject)}})).catch(()=>{});}catch{}}

}
boot().catch(()=>{document.querySelector('#main').textContent='Learning content could not be loaded safely. Please reload or report this problem to the maintainers.';});
